To make the backend "real" and professional, we need to move away from the hybrid Mock/Supabase approach and fully integrate Supabase Authentication and Database operations.

Here is the plan to fix the persistence issues (products disappearing) and add the Sign-Up flow:

1.  **Database Schema**: I will provide the SQL you need to run in your Supabase SQL Editor to create the necessary tables (`profiles`, `products`, `vendors`, `orders`) so they match the app's data structure.
2.  **Authentication**: I will split the Auth logic into `Login` and `Register` pages. New users will create an account in Supabase `auth.users` and a corresponding profile in `public.profiles`.
3.  **Context Refactor**: I will rewrite `context.tsx` to prioritize Supabase operations. When you add a product, it will wait for the database confirmation before updating the UI, ensuring data consistency.

### **Step 1: Run this SQL in Supabase**
Go to your Supabase Dashboard -> SQL Editor -> New Query, paste this, and run it. This sets up the backend structure.

```sql
-- Enable UUID extension
create extension if not exists "uuid-ossp";

-- 1. PROFILES (Extends Auth)
create table public.profiles (
  id uuid references auth.users on delete cascade not null primary key,
  email text,
  full_name text,
  avatar_url text,
  roles text[] default '{buyer}', -- Array of roles
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- 2. VENDORS
create table public.vendors (
  id uuid default uuid_generate_v4() primary key,
  user_id uuid references public.profiles(id) not null,
  store_name text not null,
  store_description text,
  store_avatar_url text,
  location text,
  is_approved boolean default true,
  rating numeric default 0,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- 3. PRODUCTS
create table public.products (
  id uuid default uuid_generate_v4() primary key,
  vendor_id uuid references public.vendors(id) not null,
  title text not null,
  description text,
  price numeric not null,
  currency text default 'GHS',
  category text,
  images text[], -- Array of image URLs/Base64
  stock int default 1,
  status text default 'pending', -- pending, approved, rejected
  location text,
  contact_phone text,
  rating numeric default 0,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- 4. ORDERS
create table public.orders (
  id uuid default uuid_generate_v4() primary key,
  buyer_id uuid references public.profiles(id) not null,
  vendor_id uuid references public.vendors(id) not null,
  items_json jsonb not null, -- Storing cart items as JSON for simplicity
  total numeric not null,
  status text default 'placed',
  delivery_option text,
  created_at timestamp with time zone default timezone('utc'::text, now())
);

-- Enable Row Level Security (Basic Policy: Public Access for Demo)
alter table public.profiles enable row level security;
alter table public.products enable row level security;
alter table public.vendors enable row level security;
alter table public.orders enable row level security;

-- Create policies (Permissive for this stage of development)
create policy "Public profiles are viewable by everyone." on public.profiles for select using (true);
create policy "Users can insert their own profile." on public.profiles for insert with check (auth.uid() = id);
create policy "Users can update own profile." on public.profiles for update using (auth.uid() = id);

create policy "Products are viewable by everyone." on public.products for select using (true);
create policy "Vendors can insert products." on public.products for insert with check (true);
create policy "Vendors can update products." on public.products for update using (true);

create policy "Vendors are viewable by everyone." on public.vendors for select using (true);
create policy "Users can create vendor profiles." on public.vendors for insert with check (true);

create policy "Orders viewable by involved parties" on public.orders for select using (auth.uid() = buyer_id or auth.uid() IN (select user_id from public.vendors where id = vendor_id));
create policy "Buyers can create orders" on public.orders for insert with check (auth.uid() = buyer_id);
create policy "Vendors/Buyers can update orders" on public.orders for update using (true);
```

