// context.tsx
import React, { createContext, useContext, useState, useEffect } from 'react';

// Define your types and interfaces here
interface Order {
    id: number;
    status: string;
    // ... other order fields
}

interface AppContextType {
    orders: Order[];
    loading: boolean;
    error: string | null;
    fetchData: () => Promise<void>;
    refreshData: () => Promise<void>;
}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const useApp = () => {
    const context = useContext(AppContext);
    if (!context) {
        throw new Error('useApp must be used within an AppProvider');
    }
    return context;
};

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [orders, setOrders] = useState<Order[]>([]);
    const [loading, setLoading] = useState<boolean>(true);
    const [error, setError] = useState<string | null>(null);

    const fetchData = async () => {
        setLoading(true);
        try {
            // Replace with your actual data fetching logic
            const response = await fetch('/api/orders'); // Example API endpoint
            if (!response.ok) {
                throw new Error('Network response was not ok');
            }
            const data: Order[] = await response.json();
            setOrders(data);
            setError(null);
        } catch (err: any) {
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    const refreshData = async () => {
        await fetchData(); // Just call the fetch data again
    };

    useEffect(() => {
        fetchData();
    }, []); // Run only on mount

    const value: AppContextType = {
        orders,
        loading,
        error,
        fetchData,
        refreshData, // Make sure to include refreshData in the value object
