}

const AppContext = createContext<AppContextType | undefined>(undefined);

export const AppProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [currentRole, setCurrentRole] = useState<Role>(() => {
      try { return (localStorage.getItem('lynqed_role') as Role) || 'guest'; } catch { return 'guest'; }
  });
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [toast, setToast] = useState<ToastMessage | null>(null);

  const [products, setProducts] = useState<Product[]>([]);
  const [vendors, setVendors] = useState<Vendor[]>([]);
  const [orders, setOrders] = useState<Order[]>([]);

  const [cart, setCart] = useState<CartItem[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_cart') || '[]'); } catch { return []; }
  });
  const [favorites, setFavorites] = useState<string[]>(() => {
      try { return JSON.parse(localStorage.getItem('lynqed_favs') || '[]'); } catch { return []; }
  });

  useEffect(() => { localStorage.setItem('lynqed_cart', JSON.stringify(cart)); }, [cart]);
  useEffect(() => { localStorage.setItem('lynqed_favs', JSON.stringify(favorites)); }, [favorites]);
  useEffect(() => { if (currentRole !== 'guest') localStorage.setItem('lynqed_role', currentRole); }, [currentRole]);

  useEffect(() => {
    checkSession();
    fetchData();
    const sub = supabase.channel('public:db').on('postgres_changes', { event: '*', schema: 'public' }, () => fetchData()).subscribe();
    return () => { supabase.removeChannel(sub); };
  }, []);

  const checkSession = async () => {
      try {
          const { data: { session } } = await supabase.auth.getSession();
          if (session?.user) await fetchUserProfile(session.user.id);
          else { setCurrentUser(null); setCurrentRole('guest'); }
      } catch (e) { console.error(e); } 
      finally { setIsLoading(false); }
  };

  const fetchUserProfile = async (userId: string) => {
      const persistedRole = localStorage.getItem('lynqed_role') as Role;
      const { data } = await supabase.from('profiles').select('*').eq('id', userId).single();
      if (data) {
          const user: User = { ...data, roles: data.roles || ['buyer'] };
          setCurrentUser(user);
          if (persistedRole && user.roles.includes(persistedRole)) setCurrentRole(persistedRole);
          else if (user.roles.includes('admin')) setCurrentRole('admin');
          else if (user.roles.includes('vendor')) setCurrentRole('vendor');
          else setCurrentRole('buyer');
          return user;
      }
      return null;
  };

  const fetchData = async () => {
      const { data: p } = await supabase.from('products').select('*').order('created_at', { ascending: false });
      if (p) setProducts(p as Product[]);

      const { data: v } = await supabase.from('vendors').select('*');
      if (v) setVendors(v as Vendor[]);

      const { data: o } = await supabase.from('orders').select('*').order('created_at', { ascending: false });
      if (o) {
          setOrders(o.map((x: any) => ({ ...x, items: typeof x.items === 'string' ? JSON.parse(x.items) : x.items })) as Order[]);
      }
  };

  const login = async (email: string, pass: string) => {
      const { data, error } = await supabase.auth.signInWithPassword({ email, password: pass });
      if (error) return { success: false, error: error.message };
      if (data.user) {
          const user = await fetchUserProfile(data.user.id);
          fetchData();
          return { success: true, role: user?.roles.includes('admin') ? 'admin' : user?.roles.includes('vendor') ? 'vendor' : 'buyer' };
      }
      return { success: false, error: 'User not found' };
  };

  const signup = async (email: string, password: string, fullName: string, role: Role) => {
      const { data, error } = await supabase.auth.signUp({ email, password, options: { data: { full_name: fullName, roles: [role] } } });
      if (error?.message?.includes("already registered")) {
           // Auto login attempt logic could go here
           return { success: false, error: "Email taken" };
      }
      if (data.user) {
           await supabase.from('profiles').insert({ id: data.user.id, email, name: fullName, roles: [role] });
           await login(email, password);
           return { success: true };
      }
      return { success: false };
  };

  const logout = async () => {
      await supabase.auth.signOut();
      localStorage.removeItem('lynqed_role');
      setCurrentUser(null);
      setCurrentRole('guest');
      setCart([]);
  };

  const registerVendor = async (data: any) => {
      if (!currentUser) return;
      await supabase.from('vendors').insert({
          vendorId: `v-${Date.now()}`,
          userId: currentUser.id,
          ...data,
          isApproved: false,
          rating: 5.0
      });
      showToast("Application submitted", "success");
      fetchData();
  };

  const addProduct = async (prod: any) => {
      if (!currentUser) return false;
      const { data: v } = await supabase.from('vendors').select('vendorId').eq('userId', currentUser.id).single();
      if (!v) { alert("Vendor profile not found"); return false; }

      const { customCategory, ...dbProduct } = prod;
      const { error } = await supabase.from('products').insert({ ...dbProduct, vendorId: v.vendorId, status: 'pending' });

      if (error) { alert(error.message); return false; }
      showToast("Product added!", "success");
      fetchData();
      return true;
  };

  const updateProduct = async (id: string, data: any) => {
      const { customCategory, ...dbData } = data;
      await supabase.from('products').update(dbData).eq('id', id);
      showToast("Updated", "success");
      fetchData();
  };

  const deleteProduct = async (id: string) => {
      await supabase.from('products').delete().eq('id', id);
      fetchData();
  };

  const updateProductStatus = async (id: string, status: string) => {
      await supabase.from('products').update({ status }).eq('id', id);
      fetchData();
  };

  // Cart Logic
  const addToCart = (product: Product, quantity = 1) => {
      setCart(prev => {
          const exists = prev.find(i => i.productId === product.id);
          if (exists) return prev.map(i => i.productId === product.id ? { ...i, quantity: i.quantity + quantity } : i);
          return [...prev, { productId: product.id, quantity, product }];
      });
      showToast("Added to Cart", "success");
  };

  const updateCartQuantity = (pid: string, qty: number) => {
      if (qty <= 0) { removeFromCart(pid); return; }
      setCart(prev => prev.map(i => i.productId === pid ? { ...i, quantity: qty } : i));
  };

  const removeFromCart = (pid: string) => setCart(prev => prev.filter(i => i.productId !== pid));
  const clearCart = () => setCart([]);

  const toggleFavorite = (pid: string) => {
      const isFav = favorites.includes(pid);
      setFavorites(prev => isFav ? prev.filter(i => i !== pid) : [...prev, pid]);
      showToast(isFav ? "Removed from Wishlist" : "Added to Wishlist", "info");
  };

  const placeOrder = async (option: 'delivery' | 'pickup', fee = 0) => {
      if (!currentUser) return;
      if (cart.length === 0) return;

      const byVendor: any = {};
      cart.forEach(i => {
          if (!byVendor[i.product.vendorId]) byVendor[i.product.vendorId] = [];
          byVendor[i.product.vendorId].push(i);
      });

      for (const vid in byVendor) {
          const items = byVendor[vid];
          const subtotal = items.reduce((s: number, i: any) => s + (i.product.price * i.quantity), 0);

          await supabase.from('orders').insert({
              buyerId: currentUser.id,
              vendorId: vid,
              items,
              total: subtotal + fee,
              status: 'placed',
              deliveryOption: option
          });

          // Stock
          for (const item of items) {
              const newStock = Math.max(0, item.product.stock - item.quantity);
              await supabase.from('products').update({stock: newStock}).eq('id', item.productId);
          }
      }
      showToast("Order Placed!", "success");
      clearCart();
      fetchData();
  };

  const updateOrderStatus = async (oid: string, status: string) => {
      await supabase.from('orders').update({ status }).eq('id', oid);
      fetchData();
  };

  const showToast = (message: string, type: 'success' | 'error' | 'info') => setToast({message, type});
  const hideToast = () => setToast(null);
  const resetPassword = async (email: string) => { return { success: true }; } // Mock for now or implement if needed
  const updatePassword = async (pass: string) => { return { success: true }; }
  const switchRole = (role: Role) => { if(currentUser?.roles.includes(role)) setCurrentRole(role); };
  const requestNotificationPermission = async () => true;

  return (
    <AppContext.Provider value={{
        currentUser, currentRole, products, vendors, orders, cart, favorites, toast, isLoading,
        login, signup, logout, resetPassword, updatePassword, switchRole,
        registerVendor, refreshData: fetchData,
        addProduct, updateProduct, deleteProduct, updateProductStatus,
        addToCart, updateCartQuantity, removeFromCart, clearCart, placeOrder, updateOrderStatus, toggleFavorite,
        showToast, hideToast, requestNotificationPermission
    }}>
        {children}
    </AppContext.Provider>
  );
};

